switch(prefix) {
    case '@':
        result = baseUrl+'blog.json?key=' + key.slice(1)+ '&limit=10&offset=' + offset;
        break;
    case '#':
    case '＃':
        result = baseUrl+'collection.json?key=' + key.slice(1) + '&limit=20&offset=' + offset;
        break;
    case '%':
        result = baseUrl+'grain.json?key='+key.slice(1)+'&limit=10&offset=' + offset;
        break;
    default:
